function polygon(x,y,r,n,rot=0){ctx.beginPath();for(let i=0;i<n;i++){let a=rot+i*Math.PI*2/n;let px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath()}
function draw(){ctx.save();if(screenShake>0)ctx.translate(rand(-screenShake,screenShake),rand(-screenShake,screenShake));ctx.clearRect(-20,-20,W+40,H+40);let bg=ctx.createRadialGradient(W*.5,H*.48,10,W*.5,H*.5,Math.max(W,H)*.8);bg.addColorStop(0,'#11212a');bg.addColorStop(.58,'#09151d');bg.addColorStop(1,'#050b10');ctx.fillStyle=bg;ctx.fillRect(-20,-20,W+40,H+40);
// distant starfield and restrained arena grid
for(const s of stars){ctx.globalAlpha=s.a*(.72+.28*Math.sin(gameTime*.8+s.p));ctx.fillStyle='#a1e8ed';ctx.fillRect(s.x,s.y,s.r,s.r)}ctx.globalAlpha=1;
ctx.strokeStyle='rgba(72,139,151,.055)';ctx.lineWidth=1;let grid=48,ox=(gameTime*5)%grid,oy=(gameTime*2)%grid;for(let x=-grid+ox;x<W;x+=grid){ctx.beginPath();ctx.moveTo(x,75);ctx.lineTo(x,H);ctx.stroke()}for(let y=75-grid+oy;y<H;y+=grid){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
for(let d of decor){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);ctx.strokeStyle='rgba(80,143,153,.13)';ctx.lineWidth=1;if(d.type===0){polygon(0,0,d.r,6,.1);ctx.stroke();ctx.beginPath();ctx.arc(0,0,d.r*.55,0,Math.PI*2);ctx.stroke()}else{ctx.strokeRect(-d.r,-d.r*.55,d.r*2,d.r*1.1);ctx.beginPath();ctx.moveTo(-d.r,0);ctx.lineTo(d.r,0);ctx.stroke()}ctx.restore()}
// perimeter hazard markings
ctx.strokeStyle='rgba(76,179,187,.26)';ctx.lineWidth=1;ctx.strokeRect(12,82,W-24,H-94);ctx.fillStyle='#183d46';for(let i=0;i<8;i++){let x=22+i*34;ctx.fillRect(x,80,17,3);ctx.fillRect(x,H-14,17,3)}
for(const l of loot){ctx.save();ctx.translate(l.x,l.y);ctx.rotate(gameTime*2);ctx.shadowBlur=15;ctx.shadowColor=l.type==='xp'?'#68f3ff':'#c8ff6a';ctx.fillStyle=l.type==='xp'?'#68f3ff':'#c8ff6a';polygon(0,0,l.r,4,Math.PI/4);ctx.fill();ctx.restore()}
for(const b of bullets){ctx.save();ctx.strokeStyle=b.crit?'#c9ff70':'#b4fcff';ctx.lineWidth=b.crit?4:2.5;ctx.shadowBlur=10;ctx.shadowColor=b.crit?'#c9ff70':'#68f3ff';ctx.beginPath();ctx.moveTo(b.x-b.vx*.025,b.y-b.vy*.025);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore()}
for(const b of hostile){ctx.fillStyle='#ff637c';ctx.shadowBlur=13;ctx.shadowColor='#ff334e';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffc0c8';ctx.lineWidth=1;ctx.stroke()}
for(const e of enemies){ctx.save();ctx.translate(e.x,e.y);let boss=e.kind==='boss',tank=e.kind==='tank',shootr=e.kind==='shooter',runner=e.kind==='runner',col=boss?'#ff536f':tank?'#ff8b57':shootr?'#b68bff':runner?'#f7ca63':'#ff7180';ctx.rotate(angle(e,player)+Math.PI/2);ctx.shadowBlur=boss?22:12;ctx.shadowColor=col;ctx.fillStyle=col;if(boss){polygon(0,0,e.r,8,Math.PI/8);ctx.fill();ctx.fillStyle='#341b2b';polygon(0,0,e.r*.54,6,0);ctx.fill();ctx.fillStyle='#ffd2c9';ctx.fillRect(-5,-e.r*.76,10,5);ctx.fillRect(-5,e.r*.62,10,5)}else if(tank){polygon(0,0,e.r,6,Math.PI/6);ctx.fill();ctx.fillStyle='#572d32';polygon(0,0,e.r*.48,6,0);ctx.fill()}else if(shootr){ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2c1f3a';ctx.fillRect(-5,-5,10,10)}else{polygon(0,0,e.r,runner?3:4,Math.PI/4);ctx.fill();ctx.fillStyle='#4b2531';ctx.fillRect(-2,-e.r*.62,4,e.r*.48)}ctx.shadowBlur=0;ctx.restore();if(e.hp<e.maxHp||boss){ctx.fillStyle='#311a24';ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2,3);ctx.fillStyle=boss?'#ff657b':'#ff8d8d';ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2*Math.max(0,e.hp/e.maxHp),3)}}
for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.shadowBlur=8;ctx.shadowColor=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;
if(player){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.aim);if(player.invuln>0&&Math.floor(gameTime*24)%2===0)ctx.globalAlpha=.38;ctx.shadowBlur=18;ctx.shadowColor='#65f4ff';ctx.fillStyle='#68f3ff';ctx.beginPath();ctx.moveTo(17,0);ctx.lineTo(5,-11);ctx.lineTo(-8,-9);ctx.lineTo(-13,-4);ctx.lineTo(-13,4);ctx.lineTo(-8,9);ctx.lineTo(5,11);ctx.closePath();ctx.fill();ctx.fillStyle='#173944';ctx.beginPath();ctx.moveTo(7,0);ctx.lineTo(-7,-5);ctx.lineTo(-7,5);ctx.closePath();ctx.fill();ctx.fillStyle='#d5ffff';ctx.fillRect(4,-2,13,4);ctx.fillStyle='#b8ff6c';ctx.beginPath();ctx.moveTo(-13,-4);ctx.lineTo(-20,0);ctx.lineTo(-13,4);ctx.fill();ctx.restore();if(player.shield){ctx.strokeStyle='rgba(104,243,255,.35)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x,player.y,25+Math.sin(gameTime*4)*2,0,Math.PI*2);ctx.stroke()}}
// twin stick affordances
for(let stick of [moveStick,aimStick])if(stick){ctx.globalAlpha=.34;ctx.strokeStyle='#83f7ff';ctx.fillStyle='#83f7ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(stick.origin.x,stick.origin.y,39,0,Math.PI*2);ctx.stroke();let dx=stick.pos.x-stick.origin.x,dy=stick.pos.y-stick.origin.y,m=Math.hypot(dx,dy),scale=Math.min(1,m/44),x=stick.origin.x+(m?dx/m*scale*27:0),y=stick.origin.y+(m?dy/m*scale*27:0);ctx.beginPath();ctx.arc(x,y,13,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
if(state==='playing'&&toast&&gameTime<toastUntil){ctx.globalAlpha=Math.min(1,(toastUntil-gameTime)*2);ctx.textAlign='center';ctx.font='700 18px "Space Mono", monospace';ctx.fillStyle='#c8ff6a';ctx.shadowBlur=14;ctx.shadowColor='#c8ff6a';ctx.fillText(toast,W/2,H*.25);ctx.shadowBlur=0;ctx.globalAlpha=1}ctx.restore()}
function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
</script>
