function spawnEnemy(kind){let edge=Math.floor(Math.random()*4),pad=28,x=edge===0?-pad:edge===1?W+pad:rand(0,W),y=edge===2?-pad:edge===3?H+pad:rand(100,H);let e={x,y,kind,r:kind==='tank'?19:kind==='shooter'?13:kind==='boss'?32:11,hp:kind==='tank'?100:kind==='shooter'?45:kind==='boss'?950:34,maxHp:kind==='tank'?100:kind==='shooter'?45:kind==='boss'?950:34,speed:kind==='tank'?48:kind==='shooter'?67:kind==='boss'?37:kind==='runner'?132:83,damage:kind==='boss'?22:kind==='tank'?18:kind==='runner'?9:12,fire:rand(.8,2),phase:rand(0,6.28)};enemies.push(e);if(kind==='boss')boss=e}
function spawnWave(){wave++;quota=12+(wave-1)*5;kills=0;spawnTimer=1.5;showToast('THREAT LEVEL INCREASED');if(wave%4===0){spawnEnemy('boss');for(let i=0;i<3+wave;i++)spawnEnemy(Math.random()<.5?'grunt':'runner')}}
let toast='',toastUntil=0;function showToast(t){toast=t;toastUntil=gameTime+2.2}
function burst(x,y,color,n=8,power=100){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=rand(power*.25,power),life=rand(.2,.6);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life,max:life,r:rand(1.5,4),color})}}
function shoot(){if(shotTimer>0)return;shotTimer=player.fireRate;let target;if(aimStick){let dx=aimStick.pos.x-aimStick.origin.x,dy=aimStick.pos.y-aimStick.origin.y;if(Math.hypot(dx,dy)>7)player.aim=Math.atan2(dy,dx);target=null}else if(pointer.down){player.aim=angle(player,pointer);target=null}else{target=enemies.reduce((a,e)=>!a||dist(player,e)<dist(player,a)?e:a,null)}let a=target?angle(player,target):player.aim;for(let j=0;j<1;j++){let spread=rand(-.025,.025),critical=Math.random()<player.crit;bullets.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a+spread)*player.bulletSpeed,vy:Math.sin(a+spread)*player.bulletSpeed,damage:player.damage*(critical?2:1),life:1.15,r:critical?5:3.5,crit:critical})}burst(player.x+Math.cos(a)*19,player.y+Math.sin(a)*19,'#9ffaff',2,45)}
function dash(){if(state!=='playing'||dashCd>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(moveStick){dx=moveStick.pos.x-moveStick.origin.x;dy=moveStick.pos.y-moveStick.origin.y}if(Math.hypot(dx,dy)<.1){dx=Math.cos(player.aim);dy=Math.sin(player.aim)}let len=Math.hypot(dx,dy);player.vx=dx/len*620;player.vy=dy/len*620;player.invuln=.42;dashCd=4.2;screenShake=5;for(let i=0;i<12;i++)burst(player.x,player.y,'#6bf2ff',1,180)}
function nova(){if(state!=='playing'||novaCd>0)return;novaCd=10;screenShake=12;let radius=190;for(let e of enemies)if(dist(player,e)<radius){damageEnemy(e,(player.novaDmg||65),true)}for(let i=0;i<60;i++){let a=i/60*Math.PI*2;particles.push({x:player.x,y:player.y,vx:Math.cos(a)*rand(140,310),vy:Math.sin(a)*rand(140,310),life:.55,max:.55,r:rand(2,5),color:i%2?'#66f3ff':'#c6ff70'})}showToast('PULSE NOVA // RELEASED')}
function damageEnemy(e,n,heavy=false){e.hp-=n;if(e.hp<=0){let idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);if(e===boss)boss=null;kills++;score++;credits+=e.kind==='boss'?150:e.kind==='tank'?12:5;player.xp+=e.kind==='boss'?140:e.kind==='tank'?28:e.kind==='shooter'?20:14;if(player.regen)player.hp=Math.min(player.maxHp,player.hp+player.regen);burst(e.x,e.y,e.kind==='boss'?'#ff536f':'#ff8293',e.kind==='boss'?30:10,e.kind==='boss'?220:120);if(Math.random()<.48||e.kind==='boss')loot.push({x:e.x,y:e.y,type:e.kind==='boss'?'heal':'xp',value:e.kind==='boss'?35:10+Math.floor(wave/3),r:6,life:18});if(kills>=quota&&!boss)spawnWave();if(player.xp>=player.nextXp)levelUp()}else{if(!heavy)burst(e.x,e.y,'#ffb1b8',2,40)}}
function hitPlayer(dmg){if(player.invuln>0)return;player.hp-=dmg*(1-(player.armor||0));player.lastHit=gameTime;player.invuln=.45;screenShake=6;burst(player.x,player.y,'#ff5376',9,115);if(player.hp<=0){player.hp=0;gameOver()}}
function gameOver(){state='over';$('hud').classList.remove('active');$('pause').classList.remove('show');if(score>best){best=score;localStorage.setItem('voidBest',best)}$('runSummary').textContent=`You survived ${formatTime(elapsed)}, neutralized ${score} hostiles, and banked ${credits} credits.`;$('bestScore').textContent=`BEST: ${best} HOSTILES`;$('gameover').classList.add('show')}
function formatTime(s){let m=Math.floor(s/60),ss=Math.floor(s%60);return String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0')}
function updateHud(){if(!player)return;$('waveNum').textContent=String(wave).padStart(2,'0');$('kills').textContent=String(kills).padStart(2,'0');$('quota').textContent=String(quota).padStart(2,'0');$('credits').textContent=String(credits).padStart(4,'0');$('clock').textContent=formatTime(elapsed);$('hptext').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('hpfill').style.width=100*player.hp/player.maxHp+'%';$('xptext').textContent=`${Math.floor(player.xp)} / ${player.nextXp} XP`;$('xpfill').style.width=100*player.xp/player.nextXp+'%';$('levelText').textContent='LV '+String(player.level).padStart(2,'0');$('dashText').textContent=dashCd<=0?'READY':dashCd.toFixed(1)+'s';$('novaText').textContent=novaCd<=0?'READY':novaCd.toFixed(1)+'s';$('dashIcon').classList.toggle('ready',dashCd<=0);$('novaIcon').classList.toggle('ready',novaCd<=0);$('bossbar').classList.toggle('show',!!boss);if(boss)$('bossfill').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%'}
function update(dt){if(state!=='playing')return;elapsed+=dt;gameTime+=dt;shotTimer-=dt;dashCd=Math.max(0,dashCd-dt);novaCd=Math.max(0,novaCd-dt);player.invuln=Math.max(0,player.invuln-dt);screenShake=Math.max(0,screenShake-dt*20);if(player.regen&&gameTime-player.lastHit>2)player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);
let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(moveStick){dx=(moveStick.pos.x-moveStick.origin.x)/42;dy=(moveStick.pos.y-moveStick.origin.y)/42}let mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}let speed=player.speed;player.x=clamp(player.x+dx*speed*dt+(player.vx||0)*dt,20,W-20);player.y=clamp(player.y+dy*speed*dt+(player.vy||0)*dt,87,H-20);player.vx=(player.vx||0)*Math.pow(.02,dt);player.vy=(player.vy||0)*Math.pow(.02,dt);
if(aimStick){let ax=aimStick.pos.x-aimStick.origin.x,ay=aimStick.pos.y-aimStick.origin.y;if(Math.hypot(ax,ay)>8)player.aim=Math.atan2(ay,ax)}else if(pointer.down)player.aim=angle(player,pointer);shoot();
if(!boss&&gameTime>spawnTimer){spawnTimer=gameTime+Math.max(.32,1.15-wave*.055);let k=Math.random();spawnEnemy(wave>=3&&k<.12?'shooter':wave>=2&&k<.26?'tank':wave>=2&&k<.43?'runner':'grunt')}
for(let i=enemies.length-1;i>=0;i--){let e=enemies[i],a=angle(e,player),d=dist(e,player),speed=e.speed*(1+wave*.035);e.phase+=dt*3;if(e.kind==='shooter'){if(d>265){e.x+=Math.cos(a)*speed*dt;e.y+=Math.sin(a)*speed*dt}else if(d<195){e.x-=Math.cos(a)*speed*dt;e.y-=Math.sin(a)*speed*dt}e.fire-=dt;if(e.fire<=0&&d<470){e.fire=rand(1.5,2.4);let aa=angle(e,player);hostile.push({x:e.x,y:e.y,vx:Math.cos(aa)*225,vy:Math.sin(aa)*225,r:5,damage:11,life:3})}}else if(e.kind==='boss'){e.x+=Math.cos(a)*speed*dt;e.y+=Math.sin(a)*speed*dt+Math.sin(e.phase)*17*dt;e.fire-=dt;if(e.fire<=0){e.fire=1.5;for(let j=-2;j<=2;j++){let aa=a+j*.19;hostile.push({x:e.x,y:e.y,vx:Math.cos(aa)*215,vy:Math.sin(aa)*215,r:7,damage:15,life:4})}}}else{e.x+=Math.cos(a)*speed*dt;e.y+=Math.sin(a)*speed*dt}
if(d<e.r+player.r)hitPlayer(e.damage*dt*2.7)}
for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;for(let e of enemies)if(Math.hypot(b.x-e.x,b.y-e.y)<e.r+b.r){damageEnemy(e,b.damage);hit=true;break}if(hit||b.life<=0||b.x<0||b.x>W||b.y<0||b.y>H)bullets.splice(i,1)}
for(let i=hostile.length-1;i>=0;i--){let b=hostile[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(Math.hypot(b.x-player.x,b.y-player.y)<b.r+player.r){hitPlayer(b.damage);hostile.splice(i,1)}else if(b.life<=0||b.x<0||b.x>W||b.y<0||b.y>H)hostile.splice(i,1)}
for(let i=loot.length-1;i>=0;i--){let l=loot[i],d=dist(l,player);l.life-=dt;if(d<player.magnet){l.x+=(player.x-l.x)*Math.min(1,dt*4);l.y+=(player.y-l.y)*Math.min(1,dt*4)}if(d<player.r+10){if(l.type==='xp'){player.xp+=l.value;if(player.xp>=player.nextXp)levelUp()}else player.hp=Math.min(player.maxHp,player.hp+l.value);burst(l.x,l.y,l.type==='xp'?'#68f3ff':'#c8ff6a',6,70);loot.splice(i,1)}else if(l.life<=0)loot.splice(i,1)}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}updateHud()}
