addEventListener('keydown',e=>onKey(e,true));addEventListener('keyup',e=>onKey(e,false));
function localPos(e){let r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);const p=localPos(e);if(e.pointerType==='mouse'){pointer=p;pointer.down=true}else{touches.set(e.pointerId,p);if(p.x<W*.5&&!moveStick)moveStick={id:e.pointerId,origin:p,pos:p};else if(!aimStick)aimStick={id:e.pointerId,origin:p,pos:p}}});
canvas.addEventListener('pointermove',e=>{const p=localPos(e);if(e.pointerType==='mouse')pointer=p;if(moveStick?.id===e.pointerId)moveStick.pos=p;if(aimStick?.id===e.pointerId)aimStick.pos=p;});
function pointerEnd(e){if(e.pointerType==='mouse')pointer.down=false;touches.delete(e.pointerId);if(moveStick?.id===e.pointerId)moveStick=null;if(aimStick?.id===e.pointerId)aimStick=null}
canvas.addEventListener('pointerup',pointerEnd);canvas.addEventListener('pointercancel',pointerEnd);canvas.addEventListener('contextmenu',e=>e.preventDefault());
const upgrades=[{icon:'⚡',name:'Overclocked Coil',desc:'Fire 22% faster.',apply:p=>p.fireRate*=.78},{icon:'◉',name:'Hotter Payload',desc:'Weapon damage +35%.',apply:p=>p.damage*=1.35},{icon:'⟡',name:'Reflex Booster',desc:'Movement speed +14%.',apply:p=>p.speed*=1.14},{icon:'✚',name:'Nanite Repair',desc:'Restore 35% hull and gain +15 max hull.',apply:p=>{p.maxHp+=15;p.hp=Math.min(p.maxHp,p.hp+p.maxHp*.35)}},{icon:'◎',name:'Magnetic Field',desc:'Collect XP from further away.',apply:p=>p.magnet+=65},{icon:'⌁',name:'Phase Capacitor',desc:'Dash recharges 30% faster.',apply:p=>dashCd=Math.max(0,dashCd-2.5)},{icon:'✳',name:'Nova Amplifier',desc:'Pulse nova deals +50% damage.',apply:p=>p.novaDmg=(p.novaDmg||65)*1.5},{icon:'⌖',name:'Targeting AI',desc:'Critical hit chance +12%.',apply:p=>p.crit=Math.min(.65,p.crit+.12)},{icon:'⛨',name:'Ablative Plating',desc:'Restore 20 hull and reduce damage taken.',apply:p=>{p.hp=Math.min(p.maxHp,p.hp+20);p.armor=(p.armor||0)+.16}},{icon:'⟳',name:'Life Siphon',desc:'Eliminate foes to recover a little hull.',apply:p=>p.regen+=.75}];
function levelUp(){state='upgrade';player.level++;player.xp-=player.nextXp;player.nextXp=Math.floor(player.nextXp*1.35);player.hp=Math.min(player.maxHp,player.hp+8);$('upgradeLevel').textContent='LV '+String(player.level).padStart(2,'0');let picks=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);$('choices').innerHTML='';picks.forEach((u,i)=>{let b=document.createElement('button');b.className='choice';b.innerHTML=`<div class="icon">${u.icon}<span class="upgrade-level">0${i+1}</span></div><h3>${u.name}</h3><p>${u.desc}</p>`;b.onclick=()=>{u.apply(player);state='playing';$('upgrade').classList.remove('show');updateHud()};$('choices').append(b)});$('upgrade').classList.add('show');updateHud()}

